export function initEnvelope(play){const intro=document.querySelector('#envelope-intro'),open=document.querySelector('#open-envelope');function fallback(){play();document.addEventListener('pointerdown',e=>{if(e.target.id!=='music-toggle')play()},{once:true})}let seen=false;try{seen=sessionStorage.getItem('wedding-envelope-opened')==='yes'}catch{}if(!intro||!open||seen||typeof intro.showModal!=='function'){intro?.remove();fallback();return}let opening=false;const previousOverflow=document.body.style.overflow;function finish(){document.body.style.overflow=previousOverflow;if(intro.open)intro.close();intro.remove();try{sessionStorage.setItem('wedding-envelope-opened','yes')}catch{}const target=document.querySelector('#guest-name');if(target){target.tabIndex=-1;target.focus({preventScroll:true})}}function reveal(){if(opening)return;opening=true;play();open.disabled=true;intro.classList.add('opening');const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced){finish();return}setTimeout(()=>intro.classList.add('fading'),1250);setTimeout(finish,1750)}open.addEventListener('click',reveal);intro.addEventListener('cancel',e=>{e.preventDefault();reveal()});try{intro.showModal();document.body.style.overflow='hidden';open.focus()}catch{intro.remove();document.body.style.overflow=previousOverflow;fallback()}}